import { test, expect } from '@playwright/test';

test.describe('Search Results Category Filter', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/search');
    await page.waitForLoadState('networkidle');
  });

  test('should display category filter checkboxes on search results page', async ({ page }) => {
    await page.getByRole('textbox', { name: /search/i }).fill('laptop');
    await page.getByRole('button', { name: /search/i }).click();
    await page.waitForLoadState('networkidle');

    const categorySection = page.getByRole('region', { name: /category/i });
    await expect(categorySection).toBeVisible();

    const checkboxes = page.getByRole('checkbox');
    const count = await checkboxes.count();
    expect(count).toBeGreaterThan(0);
  });

  test('should filter results when single category checkbox is selected', async ({ page }) => {
    await page.getByRole('textbox', { name: /search/i }).fill('laptop');
    await page.getByRole('button', { name: /search/i }).click();
    await page.waitForLoadState('networkidle');

    const initialResults = page.getByRole('listitem', { name: /product/i });
    const initialCount = await initialResults.count();

    const electronicsCheckbox = page.getByRole('checkbox', { name: /electronics/i });
    await electronicsCheckbox.check();
    await page.waitForLoadState('networkidle');

    const filteredResults = page.getByRole('listitem', { name: /product/i });
    const filteredCount = await filteredResults.count();

    expect(filteredCount).toBeLessThanOrEqual(initialCount);
    await expect(electronicsCheckbox).toBeChecked();
  });

  test('should filter results when multiple category checkboxes are selected', async ({ page }) => {
    await page.getByRole('textbox', { name: /search/i }).fill('phone');
    await page.getByRole('button', { name: /search/i }).click();
    await page.waitForLoadState('networkidle');

    const smartphonesCheckbox = page.getByRole('checkbox', { name: /smartphones/i });
    const accessoriesCheckbox = page.getByRole('checkbox', { name: /accessories/i });

    await smartphonesCheckbox.check();
    await page.waitForLoadState('networkidle');
    await accessoriesCheckbox.check();
    await page.waitForLoadState('networkidle');

    await expect(smartphonesCheckbox).toBeChecked();
    await expect(accessoriesCheckbox).toBeChecked();

    const results = page.getByRole('listitem', { name: /product/i });
    const count = await results.count();
    expect(count).toBeGreaterThan(0);
  });

  test('should uncheck category filter and show all results again', async ({ page }) => {
    await page.getByRole('textbox', { name: /search/i }).fill('camera');
    await page.getByRole('button', { name: /search/i }).click();
    await page.waitForLoadState('networkidle');

    const photographyCheckbox = page.getByRole('checkbox', { name: /photography/i });
    await photographyCheckbox.check();
    await page.waitForLoadState('networkidle');

    const filteredCount = await page.getByRole('listitem', { name: /product/i }).count();

    await photographyCheckbox.uncheck();
    await page.waitForLoadState('networkidle');

    const unfilteredCount = await page.getByRole('listitem', { name: /product/i }).count();

    expect(unfilteredCount).toBeGreaterThanOrEqual(filteredCount);
    await expect(photographyCheckbox).not.toBeChecked();
  });

  test('should maintain category filters when navigating between pages', async ({ page }) => {
    await page.getByRole('textbox', { name: /search/i }).fill('tablet');
    await page.getByRole('button', { name: /search/i }).click();
    await page.waitForLoadState('networkidle');

    const tabletCheckbox = page.getByRole('checkbox', { name: /tablets/i });
    await tabletCheckbox.check();
    await page.waitForLoadState('networkidle');

    const nextPageButton = page.getByRole('button', { name: /next/i });
    if (await nextPageButton.isVisible()) {
      await nextPageButton.click();
      await page.waitForLoadState('networkidle');

      await expect(tabletCheckbox).toBeChecked();
      const results = page.getByRole('listitem', { name: /product/i });
      const count = await results.count();
      expect(count).toBeGreaterThan(0);
    }
  });

  test('should display filter count badge when categories are selected', async ({ page }) => {
    await page.getByRole('textbox', { name: /search/i }).fill('watch');
    await page.getByRole('button', { name: /search/i }).click();
    await page.waitForLoadState('networkidle');

    const smartwatchCheckbox = page.getByRole('checkbox', { name: /smartwatch/i });
    const classicCheckbox = page.getByRole('checkbox', { name: /classic/i });

    await smartwatchCheckbox.check();
    await classicCheckbox.check();
    await page.waitForLoadState('networkidle');

    const filterBadge = page.getByText(/2 filters? applied/i);
    await expect(filterBadge).toBeVisible();
  });

  test('should clear all filters with clear button', async ({ page }) => {
    await page.getByRole('textbox', { name: /search/i }).fill('shoes');
    await page.getByRole('button', { name: /search/i }).click();
    await page.waitForLoadState('networkidle');

    const sportsCheckbox = page.getByRole('checkbox', { name: /sports/i });
    const casualCheckbox = page.getByRole('checkbox', { name: /casual/i });

    await sportsCheckbox.check();
    await casualCheckbox.check();
    await page.waitForLoadState('networkidle');

    const clearButton = page.getByRole('button', { name: /clear all filters/i });
    await clearButton.click();
    await page.waitForLoadState('networkidle');

    await expect(sportsCheckbox).not.toBeChecked();
    await expect(casualCheckbox).not.toBeChecked();
  });

  test('should show category filter results count', async ({ page }) => {
    await page.getByRole('textbox', { name: /search/i }).fill('book');
    await page.getByRole('button', { name: /search/i }).click();
    await page.waitForLoadState('networkidle');

    const fictionCheckbox = page.getByRole('checkbox', { name: /fiction/i });
    const fictionLabel = page.getByText(/fiction/i).first();

    const countText = await fictionLabel.textContent();
    expect(countText).toMatch(/\(\d+\)/);

    await fictionCheckbox.check();
    await page.waitForLoadState('networkidle');

    const results = page.getByRole('listitem', { name: /product/i });
    const count = await results.count();
    expect(count).toBeGreaterThan(0);
  });
});
